private formatValidationErrors(errors: Array<{instancePath: string; message: string; params?: Record<string, unknown>}> | null): string {
  if (!errors || errors.length === 0) {
    return 'Invalid input';
  }
  const messages = errors.map(err => {
    const path = err.instancePath || 'root';
    const message = err.message;
    const type = err.params?.type ? ` (expected ${err.params.type})` : '';
    return `${path}: ${message}${type}`;
  });
  return messages.join('; ');
}

async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
  const tool = this.tools.get(name);
  if (!tool) {
    log.warn('tool', 'tool not found', {name});
