  }

  const resolved = this.resolveDefinition(tool.definitionSource);
  let validator: ReturnType<Ajv['compile']> | undefined;

  if (tool.staticValidator) {
    validator = tool.staticValidator;
  } else {
    const schema = resolved.inputSchema;
    const schemaKey = schema;
    let cachedValidator = this.functionSchemaValidators.get(schemaKey);
    if (!cachedValidator) {
      cachedValidator = this.ajv.compile(schema);
      this.functionSchemaValidators.set(schemaKey, cachedValidator);
    }
    validator = cachedValidator;
